#!/bin/sh
# Prepares /certs/server.crt + /certs/server.key before nginx starts (run by entrypoint.sh).
#
#  1. server.crt + server.key present (and not generated by us)  -> used as-is
#  2. ca.crt + ca.key present (your own self-signed root)        -> signs a server cert
#  3. nothing present                                            -> creates a root CA, then signs
#     (the certificate then lists every registry hostname you configured)
#
# A server cert we generated is reissued automatically when TLS_SANS changes,
# when it is within 30 days of expiry, when the CA no longer verifies it, or when
# TLS_REGENERATE=true. The public root (never the key) is copied to /run/public-certs/ca.crt for the UI.
set -eu
set -f   # SANs contain '*'; never let the shell expand them as file globs

CERTS="${CERTS:-/certs}"
PUBLIC="${PUBLIC_DIR:-/run/public-certs}"   # not under /certs, so /certs can be mounted read-only
MARKER="$CERTS/.generated"
CA_DAYS="${TLS_CA_DAYS:-3650}"
CERT_DAYS="${TLS_CERT_DAYS:-825}"

log() { echo "[tls] $*"; }

mkdir -p "$PUBLIC"
chmod 755 "$PUBLIC"

# ---- Build the subjectAltName list ------------------------------------------
SAN="DNS:localhost,IP:127.0.0.1"
# Clients use the real registry names, so the certificate must cover each of them.
for h in ${TLS_HOSTS:-}; do
  SAN="$SAN,DNS:$h"
done
for entry in $(echo "${TLS_SANS:-}" | tr ',' ' '); do
  case "$entry" in
    DNS:*|IP:*) SAN="$SAN,$entry" ;;
    *[!0-9.]*)  SAN="$SAN,DNS:$entry" ;;   # anything but digits and dots is a hostname
    *)          SAN="$SAN,IP:$entry" ;;
  esac
done

issue_server_cert() {
  tmp="$(mktemp -d)"
  cat > "$tmp/ext.cnf" <<EXT
basicConstraints=critical,CA:FALSE
keyUsage=critical,digitalSignature,keyEncipherment
extendedKeyUsage=serverAuth
subjectAltName=$SAN
subjectKeyIdentifier=hash
authorityKeyIdentifier=keyid,issuer
EXT
  openssl req -new -newkey rsa:2048 -nodes \
    -keyout "$CERTS/server.key" -out "$tmp/server.csr" \
    -subj "/O=Registry Cache/CN=registry-cache" 2>/dev/null
  openssl x509 -req -in "$tmp/server.csr" \
    -CA "$CERTS/ca.crt" -CAkey "$CERTS/ca.key" -CAcreateserial -CAserial "$tmp/ca.srl" \
    -days "$CERT_DAYS" -sha256 -extfile "$tmp/ext.cnf" -out "$tmp/leaf.crt" 2>/dev/null
  cat "$tmp/leaf.crt" "$CERTS/ca.crt" > "$CERTS/server.crt"   # full chain
  chmod 600 "$CERTS/server.key"
  chmod 644 "$CERTS/server.crt"
  echo "$SAN" > "$MARKER"
  rm -rf "$tmp"
  log "issued server certificate for: $SAN"
}

create_root_ca() {
  tmp="$(mktemp -d)"
  cat > "$tmp/ca.cnf" <<CNF
[req]
distinguished_name = dn
x509_extensions    = v3_ca
prompt             = no
[dn]
O  = Registry Cache
CN = Registry Cache Root CA
[v3_ca]
basicConstraints     = critical,CA:TRUE,pathlen:0
keyUsage             = critical,keyCertSign,cRLSign
subjectKeyIdentifier = hash
CNF
  openssl req -x509 -newkey rsa:4096 -nodes -sha256 -days "$CA_DAYS" \
    -config "$tmp/ca.cnf" -keyout "$CERTS/ca.key" -out "$CERTS/ca.crt" 2>/dev/null
  chmod 600 "$CERTS/ca.key"
  chmod 644 "$CERTS/ca.crt"
  rm -rf "$tmp"
  log "created new root CA (valid $CA_DAYS days)"
}

publish_ca() {
  if [ -f "$CERTS/ca.crt" ]; then
    cp "$CERTS/ca.crt" "$PUBLIC/ca.crt"
    chmod 644 "$PUBLIC/ca.crt"
    log "root CA fingerprint: $(openssl x509 -in "$CERTS/ca.crt" -noout -fingerprint -sha256 | cut -d= -f2)"
  else
    rm -f "$PUBLIC/ca.crt"
    log "no ca.crt found; clients must obtain the issuing root another way"
  fi
}

# ---- 1. Operator-supplied server certificate ---------------------------------
if [ -f "$CERTS/server.crt" ] && [ -f "$CERTS/server.key" ] && [ ! -f "$MARKER" ]; then
  log "using provided server.crt / server.key"
  publish_ca
else
  # ---- 2/3. Sign with an existing root, or create one ------------------------
  if [ -f "$CERTS/ca.crt" ] && [ ! -f "$CERTS/ca.key" ]; then
    log "ERROR: ca.crt found without ca.key. Add ca.key so a server cert can be signed,"
    log "       or provide server.crt + server.key instead."
    exit 1
  fi
  if [ ! -f "$CERTS/ca.crt" ]; then
    create_root_ca
  else
    log "using your root CA from $CERTS/ca.crt"
  fi

  need=no
  [ -f "$CERTS/server.crt" ] && [ -f "$CERTS/server.key" ] || need=yes
  [ "${TLS_REGENERATE:-false}" = "true" ] && need=yes
  [ "$(cat "$MARKER" 2>/dev/null || true)" = "$SAN" ] || need=yes
  if [ "$need" = no ]; then
    openssl x509 -checkend 2592000 -noout -in "$CERTS/server.crt" >/dev/null 2>&1 || need=yes
    openssl verify -CAfile "$CERTS/ca.crt" "$CERTS/server.crt" >/dev/null 2>&1 || need=yes
  fi

  if [ "$need" = yes ]; then
    issue_server_cert
  else
    log "existing server certificate is still valid"
  fi
  publish_ca
fi

# nginx always reads the certificate from here, whichever branch ran.
TLS_RUN="${TLS_RUN:-/run/tls}"
mkdir -p "$TLS_RUN"
ln -sf "$CERTS/server.crt" "$TLS_RUN/server.crt"
ln -sf "$CERTS/server.key" "$TLS_RUN/server.key"
